// A JSX runtime that records what it's given (as React's would receive it).
const name = (t) => (typeof t === "function" ? t.name : typeof t === "symbol" ? "Fragment" : t);
const node = (static_) => (type, props, key) => ({ type: name(type), static: static_, key, props });
exports.jsx = node(false);
exports.jsxs = node(true);
exports.Fragment = Symbol("Fragment");
exports.show = function show(n) {
  if (n == null || typeof n !== "object") return JSON.stringify(n);
  if (Array.isArray(n)) return "[" + n.map(show).join(", ") + "]";
  const { children, ...rest } = n.props;
  const attrs = Object.keys(rest).map((k) => ` ${k}=${JSON.stringify(rest[k])}`).join("");
  const kids = children === undefined ? "" : show(children);
  return `<${n.type}${n.key !== undefined ? " #" + n.key : ""}${n.static ? " static" : ""}${attrs}>${kids}</${n.type}>`;
};
